def keyringFilter = logic.param('keyringFilter').getReal()
def keyringList = logic.param('keyringList').getReal()
if (keyringList == null || keyringList.isEmpty()) {
    def srfpersonname = keyringFilter.get('personname')
    def srfpersonid = keyringFilter.get('n_scope_id_eq')
    def de = sys.dataentity('Base.KEYRING')
    def keyring = de.entity()
    keyring.set('name', srfpersonname + '的密钥')
    keyring.set('scope_type', 'user')
    keyring.set('scope_id', srfpersonid)
    keyring.create()
}
